function allCommandedBlocks(map, state, post) {
	const templates = map.world.organisationTemplates ?? [];
	const formationIds = new Set(templates.flatMap((t) => t.posts.map((p) => p.id)));
	if (!templates.some((t) => t.army === post) && !formationIds.has(post)) return commandedBlocks(state, post);
	return Object.keys(state.forceAssignments).filter((id) => {
		const assigned = state.forceAssignments[id] ?? null;
		return assigned === post || assigned !== null && formationIds.has(assigned) && withinCommand(state, assigned, post);
	}).sort(strictCompare);
}

function withinCommand(state, post, command) {
	const seen = new Set();
	while (post !== null && !seen.has(post)) {
		if (post === command) return true;
		seen.add(post);
		post = postStateOf(state, post).postParent;
	}
	return false;
}

function formationPost(map, post) {
	return (map.world.organisationTemplates ?? []).some((t) => t.posts.some((p) => p.id === post));
}

function rankOn(ranks, isoDate) {
	let held = null;
	for (const r of ranks) if (strictCompare(latestDayOf(r.from), isoDate) <= 0 && (r.until === undefined || isoDate < r.until)) held = {
		rankTerm: r.rank,
		rankSince: r.from
	};
	return held;
}

function headquartersOf(world, state, post) {
	const faction = postFaction(world, state, post);
	if (faction !== null && world.factionIds.includes(faction) && state.postStates[post]?.postHolder === world.faction(faction).principal) return capitalOf(state, faction);
	// Institutional offices stay with their government even when they own distant forces.
	if (postRole(world, state, post) === "office") {
		if (faction !== null && world.factionIds.includes(faction)) return capitalOf(state, faction);
		const seat = postStateOf(state, post).postSeat;
		if (seat !== null) return seat;
		throw new RangeError(`office ${post} has no government's seat`);
	}
	const body = mainBody(state, post, world.map.forceTotalsCache, world.map);
	if (body !== null) return state.forceLocations[body].locRegion;
	const p = postStateOf(state, post);
	if (p.postSeat !== null) return p.postSeat;
	if (faction !== null && world.factionIds.includes(faction)) return capitalOf(state, faction);
	throw new RangeError(`post ${post} has no blocks, no seat and no side's capital to stand in`);
}

function mainBody(state, post, cache, map) {
	let best = null;
	let bestMen = -1;
	for (const b of map === undefined ? commandedBlocks(state, post) : allCommandedBlocks(map, state, post)) {
		const men = forceTotals(state.forceBlockStates[b], cache).fbStrength ?? 0;
		if (men > bestMen) {
			best = b;
			bestMen = men;
		}
	}
	return best;
}

function postRole(world, state, post) {
	return world.roleOf(postStateOf(state, post).postKind);
}

function receivedCandidates(world, state, principal, faction, fromPost = null, picture) {
	const view = picture ?? viewFor(world, state, seatIdFor(principal), createViewCache());
	const promised = new Set(unansweredAppointments(state, principal).map((a) => a.appointmentPerson));
	const held = new Map(view.posts.flatMap((p) => p.holder === null ? [] : [[p.holder, p.post]]));
	const side = new Map(world.map.world.people.map((p) => [p.id, p.faction]));
	const unavailable = new Map();
	const reports = [...view.reports].filter((r) => r.day <= state.stateDay && r.receivedDay <= state.stateDay).sort((a, b) => a.day - b.day || (a.hour ?? -1) - (b.hour ?? -1) || strictCompare(a.id, b.id));
	for (const r of reports) {
		if (r.type === "wire-dispatch" && r.subtype === null && r.subjectKind === "person" && r.author === r.subjectId && r.claims.some((c) => c.kind === "service-choice" && c.token === "resign" && c.value === 1)) {
			side.set(r.author, world.map.world.people.find((p) => p.id === r.author)?.service?.toFaction ?? null);
			if (side.get(r.author) === faction && unavailable.get(r.author) === "other_side") unavailable.delete(r.author);
		}
		for (const claim of r.claims) {
			if (claim.kind === "appointment-refused" && (claim.token === "not_serving" || claim.token === "person_holds_post" || claim.token === "other_side")) unavailable.set(r.author, claim.token);
			if (claim.kind === "verb-answered" && claim.value === 1 && claim.token?.startsWith("relieve:") && unavailable.get(r.author) === "person_holds_post") unavailable.delete(r.author);
		}
		if (r.subjectKind === "post" && r.claims.some((c) => c.kind === "commander-lost")) {
			// Recover the holder just before this paper from the same opening/received projection, not the lost man's status.
			const earlier = peopleProjection(world, principal, faction, reports.filter((p) => p !== r && (p.day < r.day || p.day === r.day && strictCompare(p.id, r.id) < 0)), () => null, state.stateDay, state.calendarStart);
			const person = earlier.posts.find((p) => p.post === r.subjectId)?.holder;
			if (person != null) unavailable.set(person, "not_serving");
		}
	}
	const ranks = new Map(world.map.world.vocabularies.ranks.map((r, i) => [r.id, i]));
	return world.map.world.people.filter((p) => (p.requiresIntroduction !== true || view.people.some((known) => known.person === p.id)) && p.id !== principal && side.get(p.id) === faction && (held.get(p.id) ?? null) === fromPost && !unavailable.has(p.id) && !promised.has(p.id)).map((p) => ({
		person: p.id,
		kind: p.kind,
		seniority: Math.max(-1, ...Object.values(ranksOn(world.map, p.ranks, world.start.startDate)).map((r) => ranks.get(r.rankTerm) ?? -1))
	})).sort((a, b) => b.seniority - a.seniority || strictCompare(a.person, b.person));
}

function principalMenu(world, state, faction, ground, cache, picture) {
	const f = world.faction(faction);
	const receivedView = picture ?? viewFor(world, state, seatIdFor(f.principal), cache);
	const sides = receivedDepartmentSides(world, receivedView);
	const knownPosts = new Map(receivedView.posts.map((p) => [p.post, p]));
	// Only public declared structure for a post already named in this seat's establishment or correspondence.
	const structure = (id) => {
		const opening = world.start.posts.find((p) => p.id === id);
		const declared = opening ?? world.start.temporaryPosts.find((p) => p.id === id);
		if (declared === undefined) return undefined;
		const today = formatIsoDate(dateOfDay(world.start.startDate, receivedView.day));
		const schedule = opening?.departmentChanges.filter((c) => c.on <= today).sort((a, b) => strictCompare(a.on, b.on)).at(-1);
		return {
			...declared,
			department: schedule?.department ?? declared.department
		};
	};
	const side = (id) => {
		const p = structure(id);
		return p === undefined ? null : sides.get(p.department) ?? null;
	};
	// Own-force records identify commands (0064). An opening command still believed held does not disappear when
	// its whole garrison is secretly captured; the received loss closes that belief (0052).
	const blocks = (id) => {
		const templates = world.map.world.organisationTemplates ?? [];
		const forms = new Set(templates.flatMap((t) => t.posts.map((p) => p.id)));
		if (!forms.has(id) && !templates.some((t) => t.army === id)) return commandedBlocks(state, id);
		return Object.keys(state.forceAssignments).filter((key) => {
			let assigned = state.forceAssignments[key] ?? null;
			if (assigned === id) return true;
			const seen = new Set();
			while (assigned !== null && forms.has(assigned) && !seen.has(assigned)) {
				seen.add(assigned);
				assigned = knownPosts.get(assigned)?.parent ?? null;
				if (assigned === id) return true;
			}
			return false;
		});
	};
	const institutional = (id) => world.roleOf(structure(id)?.kind ?? "") === "office";
	const field = (id) => !institutional(id) && (blocks(id).length > 0 || knownPosts.get(id)?.status === "held" && (world.start.forceBlocks.some((b) => b.post === id) || world.map.world.organisationTemplates?.some((t) => t.army === id) === true));
	const relays = (id) => {
		const up = [];
		for (let parent = knownPosts.get(id)?.parent; parent != null && parent !== receivedView.post && !up.includes(parent); parent = knownPosts.get(parent)?.parent) up.push(parent);
		return up.reverse();
	};
	// Typical days to a post's seat in pack data, or where it stood at the start of play, or else his own side's capital:
	// the principal is not told where it is today (exit review P2).
	const routesTo = (id) => {
		const p = structure(id);
		const capital = capitalOf(state, faction);
		const to = institutional(id) ? capital : p?.region ?? world.start.temporaryPosts.find((p) => p.id === id)?.region ?? world.startHeadquarters(id) ?? capital;
		const routes = [];
		for (const route of ORDER_ROUTES) {
			const l = routeLatency(ground.latency, world.rules.latency, route, capital, to, faction, null);
			if (l.ok) routes.push({
				route,
				typicalDays: l.latency.days,
				price: route === "special-messenger" ? world.rules.latency.specialMessengerPrice : 0
			});
		}
		return routes;
	};
	const raisingKinds = new Set(world.map.world.rules.recruitment.raisingPostKinds);
	const selfGoverning = new Set(world.map.world.vocabularies.departmentKinds.filter((k) => k.selfGoverning).map((k) => k.id));
	const raisesRegiments = (id) => {
		const p = structure(id);
		if (p === undefined) return false;
		const dept = world.map.world.departments.find((d) => d.id === p.department);
		return raisingKinds.has(p.kind) && p.region !== null && !selfGoverning.has(dept?.kind ?? "");
	};
	// The posts as he believes them (0052; lane 1.12): a field post whose commander a battle took stays on his menu, with
	// the man he lost, until the report of it reaches him; an order he sends it meanwhile comes back undelivered.
	const ownPosts = receivedView.posts.filter((p) => side(p.post) === faction).map((p) => p.post).sort(strictCompare);
	const commandable = ownPosts.filter((id) => knownPosts.get(id).status === "held" && knownPosts.get(id).holder !== null && field(id)).map((id) => ({
		post: id,
		holder: knownPosts.get(id).holder,
		relays: relays(id),
		routes: routesTo(id),
		...receivedStrength(state, f.principal, id),
		raising: raisesRegiments(id),
		inTransit: inTransitTo(state, f.principal, id)
	}));
	const raising = receivedView.posts.filter((p) => p.status === "held" && p.holder !== null && (side(p.post) === faction || side(p.post) === null) && raisesRegiments(p.post)).map((p) => ({
		post: p.post,
		holder: p.holder,
		routes: routesTo(p.post),
		called: calledOn(state, f.principal, p.post)
	}));
	// Only received vacancies in commands held at the opening; unknown holders and unreceived losses stay unchanged.
	const heldAtStart = new Set(world.start.posts.filter((p) => p.holder !== null).map((p) => p.id));
	const vacancies = ownPosts.filter((id) => !formationPost(world.map, id) && knownPosts.get(id).status === "vacant" && heldAtStart.has(id) && field(id)).map((id) => ({
		post: id,
		arm: blocks(id).length > 0 && blocks(id).every((b) => isNaval(world.map, state, b)) ? "naval" : "land",
		routes: routesTo(id),
		appointing: inTransitTo(state, f.principal, id).includes("appoint")
	}));
	const previousCandidates = cache?.candidates.get(faction);
	let candidates;
	if (previousCandidates !== undefined && previousCandidates.world === world && previousCandidates.posts === receivedView.posts && previousCandidates.reports === receivedView.reports && previousCandidates.calendar === state.calendarStart) {
		candidates = previousCandidates.candidates;
	} else {
		candidates = receivedCandidates(world, state, f.principal, faction, null, receivedView);
		if (cache !== undefined) {
			// Prove the whole graph frozen before retaining it for another request.
			candidates = freezeDeep(candidates, cache);
			cache.candidates.set(faction, {
				world,
				posts: receivedView.posts,
				reports: receivedView.reports,
				calendar: state.calendarStart,
				candidates
			});
		}
	}
	const historicalAppointees = [];
	const historicalAppointments = [];
	const history = state.seatAssignments[seatIdFor(f.principal)]?.seatDriver === "rules";
	if (history) {
		const today = formatIsoDate(dateOfDay(state.calendarStart, state.stateDay + 1));
		const rows = world.map.world.rules.ruleSeats.principals.find((r) => r.faction === faction)?.appointments ?? [];
		// An effective date makes an unsent letter due. Attention can defer sending, but a refusal is final.
		// Read only the identity of the principal's own sent letter, not its private answer or willingness.
		const issued = (post, person) => {
			const sent = (id) => {
				if (id == null) return false;
				const day = Number(id.split(".")[1]);
				if (!Number.isSafeInteger(day)) return false;
				const expected = mintMessageId(new Set(), day, f.principal, person, `verb.appoint.${post}`);
				return id === expected || id.startsWith(`${expected}.`);
			};
			return state.messagesInTransit.some((m) => sent(m.id) || m.msgTo === f.principal && sent(m.msgReport?.reportAnswers)) || Object.values(state.orderResponses).some((r) => sent(r.respOrder)) || knowledgeOf(state, seatIdFor(f.principal)).knownReports.some((k) => sent(k.knownBody.reportAnswers));
		};
		const unsent = rows.filter((a) => "onDate" in a && !issued(a.post, a.person));
		historicalAppointees.push(...new Set(unsent.map((a) => a.person)));
		historicalAppointees.sort(strictCompare);
		for (const a of [...unsent].sort((a, b) => strictCompare(a.post, b.post) || strictCompare(a.person, b.person))) {
			if (!("onDate" in a) || a.onDate > today || !candidates.some((p) => p.person === a.person) || inTransitTo(state, f.principal, a.post).includes("appoint")) continue;
			const template = world.start.temporaryPosts.find((p) => p.id === a.post);
			const kind = world.map.world.vocabularies.postKinds.find((k) => k.id === template?.kind);
			const mayEstablish = template !== undefined && !knownPosts.has(a.post) && sides.get(template.department) === faction && kind?.creatable === "appoint" && kind.temporary && (template.parent === null || knownPosts.has(template.parent) && side(template.parent) === faction);
			if (!mayEstablish && (knownPosts.get(a.post)?.status !== "vacant" || side(a.post) !== faction)) continue;
			// The letter goes to the man, not to a post that does not exist yet (the appoint verb's own route).
			const to = capitalOf(state, faction);
			const routes = ORDER_ROUTES.flatMap((route) => {
				const l = routeLatency(ground.latency, world.rules.latency, route, to, to, faction, null);
				return l.ok ? [{
					route,
					typicalDays: l.latency.days,
					price: route === "special-messenger" ? world.rules.latency.specialMessengerPrice : 0
				}] : [];
			});
			historicalAppointments.push({
				post: a.post,
				person: a.person,
				routes
			});
		}
	}
	const situations = [];
	for (const def of world.situations) {
		const r = state.situationStates[def.id];
		if (def.faction !== faction || r === undefined || r.sitStatus !== "open" || r.sitSurfacedDay === null || r.sitDelegate !== null) continue;
		const proposers = new Set(def.options.filter((o) => r.sitOpenOptions.includes(o.id)).flatMap((o) => Array.isArray(o.proposedBy) ? o.proposedBy : []));
		const consultPosts = ownPosts.filter((post) => {
			const holder = knownPosts.get(post).holder;
			if (holder === null || holder === f.principal || !proposers.has(holder)) return false;
			// Only the identity of his own sent letter is read, never its actual response or an adviser's private stance.
			const tag = `verb.consult.${def.id}.${post}`;
			const sentTo = (id, person) => {
				if (id === null || id === undefined) return false;
				const issuedDay = Number(id.split(".")[1]);
				if (!Number.isSafeInteger(issuedDay)) return false;
				const expected = mintMessageId(new Set(), issuedDay, f.principal, person, tag);
				return id === expected || id.startsWith(`${expected}.`);
			};
			if (state.messagesInTransit.some((m) => m.msgVerb?.verbIssuer === f.principal && m.msgVerb.verbKind === "consult" && m.msgVerb.verbSubject === def.id && m.msgVerb.verbPost === post || m.msgTo === f.principal && sentTo(m.msgReport?.reportAnswers, m.msgReport?.reportAuthor ?? m.msgFrom))) return false;
			if (Object.values(state.orderResponses).some((a) => a.respKind === "verb:consult" && a.respPost === post && sentTo(a.respOrder, a.respPerson))) return false;
			return !knowledgeOf(state, seatIdFor(f.principal)).knownReports.some((k) => sentTo(k.knownBody.reportAnswers, k.knownBody.reportAuthor));
		});
		situations.push({
			...situationChoice(def, r.sitOpenOptions, def.delegableTo, null),
			consultPosts
		});
	}
	const awaiting = postsInStatus(state, "ready").filter((p) => state.planRecords[p].planIssuer === f.principal && !answerInTransit(state, f.principal, p, ["go"]));
	const d = world.map.world.rules.plans.goalDefaults;
	const doctrine = doctrineView(world, state, faction, receivedView);
	const appointments = world.map.world.rules.ruleSeats.principals.find((r) => r.faction === faction)?.appointments;
	const receivedPosts = receivedView.posts;
	const receivedSides = receivedDepartmentSides(world, receivedView);
	const appointmentView = appointments?.filter((a) => "fromDate" in a).map((a) => ({
		post: a.post,
		person: a.person,
		from: a.fromPost,
		ready: state.stateDay + 1 >= daysFromCivil(parseIsoDate(a.fromDate)) - daysFromCivil(parseIsoDate(state.calendarStart)) && receivedSides.get(a.requiresDepartment) === faction && receivedCandidates(world, state, f.principal, faction, a.fromPost, receivedView).some((p) => p.person === a.person) && !receivedPosts.some((p) => p.post === a.post),
		issued: state.messagesInTransit.some((m) => m.msgVerb?.verbKind === "appoint" && m.msgVerb.verbIssuer === f.principal && m.msgVerb.verbPost === a.post) || Object.values(state.orderResponses).some((r) => r.respKind === "verb:appoint" && r.respPost === a.post && r.respPerson === a.person),
		routes: routesTo(a.fromPost ?? a.post)
	}));
	return {
		menuKind: "principal",
		faction,
		atWarSince: warSince(world, state, faction),
		doctrine: appointmentView === undefined ? doctrine : {
			...doctrine,
			appointments: appointmentView
		},
		...history ? {
			historicalAppointments,
			historicalAppointees
		} : {},
		raising,
		vacancies,
		candidates,
		attention: {
			left: attentionLeft(state, seatIdFor(f.principal)),
			costs: world.map.world.rules.people.attention.costs,
			specialMessenger: world.rules.latency.specialMessengerPrice
		},
		commandable,
		situations,
		reviews: reviewsFor(state, f.principal),
		awaiting,
		goalDefaults: {
			risk: d.risk,
			deadlineDays: d.deadlineDays,
			rail: d.rail,
			river: d.river,
			sea: d.sea,
			neutral: d.neutral,
			awaitWord: d.awaitWord,
			approveAsDrafted: d.approveAsDrafted
		}
	};
}

function peopleProjection(world, principal, faction, reports, standingFor, day, calendar) {
	if (faction === null || !world.factionIds.includes(faction) || world.faction(faction).principal !== principal) {
		return Object.freeze({
			posts: Object.freeze([]),
			people: Object.freeze([])
		});
	}
	const departments = new Set(world.map.world.departments.filter((d) => d.faction === faction).map((d) => d.id));
	const posts = new Map();
	const knownSides = new Map();
	const serviceSides = new Map();
	const postDepartments = new Map();
	const people = new Set([principal]);
	const today = calendar === null ? null : formatIsoDate(dateOfDay(calendar, day));
	// The principal knows his own opening establishment, including unfilled offices. A foreign report reveals only
	// the post it names: the foreign start's holder and chain are not read to fill that gap.
	for (const p of world.start.posts) {
		if (!departments.has(p.department)) continue;
		const scheduled = today === null ? [] : [...p.departmentChanges].filter((c) => c.on <= today).sort((a, b) => strictCompare(a.on, b.on));
		postDepartments.set(p.id, scheduled.length === 0 ? p.department : scheduled[scheduled.length - 1].department);
		const parent = scheduled.length === 0 ? p.parent : scheduled[scheduled.length - 1].parent;
		posts.set(p.id, {
			post: p.id,
			parent,
			placementKnown: true,
			holder: p.holder,
			status: p.holder === null ? "vacant" : "held",
			vacantSince: null,
			source: null,
			asOfDay: 0,
			observerReports: []
		});
		if (p.holder !== null) people.add(p.holder);
	}
	const received = reports.filter((r) => r.day <= day && r.receivedDay <= day);
	const chronological = [...received].sort((a, b) => a.day - b.day || (a.hour ?? -1) - (b.hour ?? -1) || strictCompare(a.id, b.id));
	const ensure = (id) => {
		const old = posts.get(id);
		if (old !== undefined) return old;
		// Once a paper names a post, its public department can identify a government notice.
		// Its opening holder and parent still supply no evidence about who holds it now.
		const opening = world.start.posts.find((p) => p.id === id);
		if (opening !== undefined) postDepartments.set(id, opening.department);
		const unknown = {
			post: id,
			parent: null,
			placementKnown: false,
			holder: null,
			status: "unknown",
			vacantSince: null,
			source: null,
			asOfDay: 0,
			observerReports: []
		};
		posts.set(id, unknown);
		return unknown;
	};
	const tell = (id, holder, status, r) => {
		const old = ensure(id);
		posts.set(id, {
			...old,
			holder,
			status,
			vacantSince: status === "vacant" ? r.day : null,
			source: r.id,
			asOfDay: r.day
		});
		if (holder !== null) people.add(holder);
	};
	for (const r of chronological) {
		// A notice's received paper identifies the public act. Never inspect whether its event fired in State,
		// and never interpret a decision's possible effects as an announcement that they happened.
		if (r.subjectKind === "situation") {
			const notice = world.situations.find((s) => s.id === r.subjectId);
			if (notice?.kind === "notice" && notice.report?.reportType === r.type && notice.report.subtype === r.subtype) {
				for (const effect of notice.effects) {
					if (!("propose" in effect)) continue;
					const p = effect.propose;
					if (p.owner === "command" && p.field === "department_side" && p.subject !== null && p.side !== null && p.delta > 0) knownSides.set(p.subject, p.side);
					if (p.owner === "command" && p.field === "post_succession" && p.subject !== null && p.succession !== undefined && p.succession !== null && p.delta > 0) {
						const old = ensure(p.subject);
						if (old.status === "unknown" || old.holder === p.succession.from) tell(p.subject, p.succession.to, p.succession.to === null ? "vacant" : "held", r);
					}
				}
			}
		}
		for (const via of r.via) ensure(via);
		people.add(r.author);
		if (r.subjectKind === "person") people.add(r.subjectId);
		const resigned = r.type === "wire-dispatch" && r.subtype === null && r.subjectKind === "person" && r.subjectId === r.author && r.claims.some((c) => c.kind === "service-choice" && c.token === "resign" && c.value === 1);
		if (resigned) {
			// The letter supplies the act; the public service row supplies its destination, never hidden personService.
			serviceSides.set(r.author, world.map.world.people.find((p) => p.id === r.author)?.service?.toFaction ?? null);
			if (r.authorPost !== null) {
				const old = ensure(r.authorPost);
				if (old.holder === null && old.status === "unknown") tell(r.authorPost, null, "vacant", r);
			}
			for (const post of posts.values()) if (post.holder === r.author) tell(post.post, null, "vacant", r);
		} else if (r.authorPost !== null) tell(r.authorPost, r.author, "held", r);
		if (r.subjectKind !== "post") continue;
		const post = r.subjectId;
		ensure(post);
		if (r.type === "observer-letter") {
			const old = ensure(post);
			posts.set(post, {
				...old,
				observerReports: [...old.observerReports, r.id]
			});
		}
		for (const c of r.claims) {
			if (c.kind === "organisation-post") {
				const template = (world.map.world.organisationTemplates ?? []).find((t) => t.posts.some((p) => p.id === post));
				const spec = template?.posts.find((p) => p.id === post);
				const army = world.start.posts.find((p) => p.id === template?.army) ?? world.start.temporaryPosts.find((p) => p.id === template?.army);
				if (spec !== undefined && army !== undefined && r.authorPost === template.army && (departments.has(army.department) || knownSides.get(army.department) === faction)) {
					postDepartments.set(post, army.department);
					posts.set(post, {
						...ensure(post),
						parent: c.token,
						placementKnown: true
					});
					tell(post, c.commander ?? null, c.commander == null ? "vacant" : "held", r);
				}
			} else if (c.kind === "commander-lost" || c.kind === "order-returned" && c.token === "vacant_post" || c.kind === "verb-answered" && c.token?.startsWith("relieve:") && c.value === 1) tell(post, null, "vacant", r);
			else if (c.kind === "appointment-refused" && c.token === "post_held") tell(post, null, "unknown", r);
			else if (c.kind === "order-returned" && [
				"holder_changed",
				"not_serving",
				"other_side",
				"not_raising_post"
			].includes(c.token ?? "")) tell(post, null, "unknown", r);
			else if (c.kind === "verb-answered" && c.token?.startsWith("appoint:") && c.value === 1) {
				// A received acceptance of our declared establishment identifies its public parent, never a live chain.
				const declared = world.start.temporaryPosts.find((p) => p.id === post);
				if (declared !== undefined && (departments.has(declared.department) || knownSides.get(declared.department) === faction)) {
					postDepartments.set(post, declared.department);
					posts.set(post, {
						...ensure(post),
						parent: declared.parent,
						placementKnown: true
					});
				}
				tell(post, r.author, "held", r);
			}
		}
	}
	const personViews = [...people].sort(strictCompare).map((person) => {
		let side = world.personIds.includes(person) ? world.person(person).faction : null;
		for (const post of posts.values()) {
			if (post.holder !== person) continue;
			const department = postDepartments.get(post.post);
			if (department !== undefined && knownSides.has(department)) side = knownSides.get(department);
		}
		// An explicit service choice supersedes the side inferred from a government's posts (0101, R76).
		if (serviceSides.has(person)) side = serviceSides.get(person);
		const stances = [];
		const assessments = [];
		for (const r of chronological) {
			if (r.author === person && r.type === "advice" && r.subtype === "requested" && r.advice !== null && r.claims.some((c) => c.kind === "verb-answered" && c.token?.startsWith("consult:") && c.value === 1)) {
				stances.push(Object.freeze({
					subjectKind: r.subjectKind,
					subjectId: r.subjectId,
					recommends: r.advice.recommends,
					confidence: r.advice.confidence,
					day: r.day,
					source: r.id
				}));
			}
			if (r.author !== person && r.subjectKind === "person" && r.subjectId === person && r.type === "advice" && r.advice !== null) assessments.push(r.id);
		}
		return Object.freeze({
			person,
			standing: side === faction ? standingFor(person) : null,
			stances: Object.freeze(stances),
			assessments: Object.freeze(assessments)
		});
	});
	return Object.freeze({
		posts: Object.freeze([...posts.values()].sort((a, b) => strictCompare(a.post, b.post)).map((p) => Object.freeze({
			...p,
			observerReports: Object.freeze([...p.observerReports])
		}))),
		people: Object.freeze(personViews)
	});
}

function allCommandedBlocks(map, state, post) {
	const templates = map.world.organisationTemplates ?? [];
	const formationIds = new Set(templates.flatMap((t) => t.posts.map((p) => p.id)));
	if (!templates.some((t) => t.army === post) && !formationIds.has(post)) return commandedBlocks(state, post);
	return Object.keys(state.forceAssignments).filter((id) => {
		const assigned = state.forceAssignments[id] ?? null;
		return assigned === post || assigned !== null && formationIds.has(assigned) && withinCommand(state, assigned, post);
	}).sort(strictCompare);
}

function withinCommand(state, post, command) {
	const seen = new Set();
	while (post !== null && !seen.has(post)) {
		if (post === command) return true;
		seen.add(post);
		post = postStateOf(state, post).postParent;
	}
	return false;
}

function formationPost(map, post) {
	return (map.world.organisationTemplates ?? []).some((t) => t.posts.some((p) => p.id === post));
}

function rankOn(ranks, isoDate) {
	let held = null;
	for (const r of ranks) if (strictCompare(latestDayOf(r.from), isoDate) <= 0 && (r.until === undefined || isoDate < r.until)) held = {
		rankTerm: r.rank,
		rankSince: r.from
	};
	return held;
}

function headquartersOf(world, state, post) {
	const faction = postFaction(world, state, post);
	if (faction !== null && world.factionIds.includes(faction) && state.postStates[post]?.postHolder === world.faction(faction).principal) return capitalOf(state, faction);
	// Institutional offices stay with their government even when they own distant forces.
	if (postRole(world, state, post) === "office") {
		if (faction !== null && world.factionIds.includes(faction)) return capitalOf(state, faction);
		const seat = postStateOf(state, post).postSeat;
		if (seat !== null) return seat;
		throw new RangeError(`office ${post} has no government's seat`);
	}
	const body = mainBody(state, post, world.map.forceTotalsCache, world.map);
	if (body !== null) return state.forceLocations[body].locRegion;
	const p = postStateOf(state, post);
	if (p.postSeat !== null) return p.postSeat;
	if (faction !== null && world.factionIds.includes(faction)) return capitalOf(state, faction);
	throw new RangeError(`post ${post} has no blocks, no seat and no side's capital to stand in`);
}

function mainBody(state, post, cache, map) {
	let best = null;
	let bestMen = -1;
	for (const b of map === undefined ? commandedBlocks(state, post) : allCommandedBlocks(map, state, post)) {
		const men = forceTotals(state.forceBlockStates[b], cache).fbStrength ?? 0;
		if (men > bestMen) {
			best = b;
			bestMen = men;
		}
	}
	return best;
}

function postRole(world, state, post) {
	return world.roleOf(postStateOf(state, post).postKind);
}

function receivedCandidates(world, state, principal, faction, fromPost = null, picture) {
	const view = picture ?? viewFor(world, state, seatIdFor(principal), createViewCache());
	const promised = new Set(unansweredAppointments(state, principal).map((a) => a.appointmentPerson));
	const held = new Map(view.posts.flatMap((p) => p.holder === null ? [] : [[p.holder, p.post]]));
	const side = new Map(world.map.world.people.map((p) => [p.id, p.faction]));
	const unavailable = new Map();
	const reports = [...view.reports].filter((r) => r.day <= state.stateDay && r.receivedDay <= state.stateDay).sort((a, b) => a.day - b.day || (a.hour ?? -1) - (b.hour ?? -1) || strictCompare(a.id, b.id));
	for (const r of reports) {
		if (r.type === "wire-dispatch" && r.subtype === null && r.subjectKind === "person" && r.author === r.subjectId && r.claims.some((c) => c.kind === "service-choice" && c.token === "resign" && c.value === 1)) {
			side.set(r.author, world.map.world.people.find((p) => p.id === r.author)?.service?.toFaction ?? null);
			if (side.get(r.author) === faction && unavailable.get(r.author) === "other_side") unavailable.delete(r.author);
		}
		for (const claim of r.claims) {
			if (claim.kind === "appointment-refused" && (claim.token === "not_serving" || claim.token === "person_holds_post" || claim.token === "other_side")) unavailable.set(r.author, claim.token);
			if (claim.kind === "verb-answered" && claim.value === 1 && claim.token?.startsWith("relieve:") && unavailable.get(r.author) === "person_holds_post") unavailable.delete(r.author);
		}
		if (r.subjectKind === "post" && r.claims.some((c) => c.kind === "commander-lost")) {
			// Recover the holder just before this paper from the same opening/received projection, not the lost man's status.
			const earlier = peopleProjection(world, principal, faction, reports.filter((p) => p !== r && (p.day < r.day || p.day === r.day && strictCompare(p.id, r.id) < 0)), () => null, state.stateDay, state.calendarStart);
			const person = earlier.posts.find((p) => p.post === r.subjectId)?.holder;
			if (person != null) unavailable.set(person, "not_serving");
		}
	}
	const ranks = new Map(world.map.world.vocabularies.ranks.map((r, i) => [r.id, i]));
	return world.map.world.people.filter((p) => (p.requiresIntroduction !== true || view.people.some((known) => known.person === p.id)) && p.id !== principal && side.get(p.id) === faction && (held.get(p.id) ?? null) === fromPost && !unavailable.has(p.id) && !promised.has(p.id)).map((p) => ({
		person: p.id,
		kind: p.kind,
		seniority: Math.max(-1, ...Object.values(ranksOn(world.map, p.ranks, world.start.startDate)).map((r) => ranks.get(r.rankTerm) ?? -1))
	})).sort((a, b) => b.seniority - a.seniority || strictCompare(a.person, b.person));
}

function principalMenu(world, state, faction, ground, cache, picture) {
	const f = world.faction(faction);
	const receivedView = picture ?? viewFor(world, state, seatIdFor(f.principal), cache);
	const sides = receivedDepartmentSides(world, receivedView);
	const knownPosts = new Map(receivedView.posts.map((p) => [p.post, p]));
	// Only public declared structure for a post already named in this seat's establishment or correspondence.
	const structure = (id) => {
		const opening = world.start.posts.find((p) => p.id === id);
		const declared = opening ?? world.start.temporaryPosts.find((p) => p.id === id);
		if (declared === undefined) return undefined;
		const today = formatIsoDate(dateOfDay(world.start.startDate, receivedView.day));
		const schedule = opening?.departmentChanges.filter((c) => c.on <= today).sort((a, b) => strictCompare(a.on, b.on)).at(-1);
		return {
			...declared,
			department: schedule?.department ?? declared.department
		};
	};
	const side = (id) => {
		const p = structure(id);
		return p === undefined ? null : sides.get(p.department) ?? null;
	};
	// Own-force records identify commands (0064). An opening command still believed held does not disappear when
	// its whole garrison is secretly captured; the received loss closes that belief (0052).
	const blocks = (id) => {
		const templates = world.map.world.organisationTemplates ?? [];
		const forms = new Set(templates.flatMap((t) => t.posts.map((p) => p.id)));
		if (!forms.has(id) && !templates.some((t) => t.army === id)) return commandedBlocks(state, id);
		return Object.keys(state.forceAssignments).filter((key) => {
			let assigned = state.forceAssignments[key] ?? null;
			if (assigned === id) return true;
			const seen = new Set();
			while (assigned !== null && forms.has(assigned) && !seen.has(assigned)) {
				seen.add(assigned);
				assigned = knownPosts.get(assigned)?.parent ?? null;
				if (assigned === id) return true;
			}
			return false;
		});
	};
	const institutional = (id) => world.roleOf(structure(id)?.kind ?? "") === "office";
	const field = (id) => !institutional(id) && (blocks(id).length > 0 || knownPosts.get(id)?.status === "held" && (world.start.forceBlocks.some((b) => b.post === id) || world.map.world.organisationTemplates?.some((t) => t.army === id) === true));
	const relays = (id) => {
		const up = [];
		for (let parent = knownPosts.get(id)?.parent; parent != null && parent !== receivedView.post && !up.includes(parent); parent = knownPosts.get(parent)?.parent) up.push(parent);
		return up.reverse();
	};
	// Typical days to a post's seat in pack data, or where it stood at the start of play, or else his own side's capital:
	// the principal is not told where it is today (exit review P2).
	const routesTo = (id) => {
		const p = structure(id);
		const capital = capitalOf(state, faction);
		const to = institutional(id) ? capital : p?.region ?? world.start.temporaryPosts.find((p) => p.id === id)?.region ?? world.startHeadquarters(id) ?? capital;
		const routes = [];
		for (const route of ORDER_ROUTES) {
			const l = routeLatency(ground.latency, world.rules.latency, route, capital, to, faction, null);
			if (l.ok) routes.push({
				route,
				typicalDays: l.latency.days,
				price: route === "special-messenger" ? world.rules.latency.specialMessengerPrice : 0
			});
		}
		return routes;
	};
	const raisingKinds = new Set(world.map.world.rules.recruitment.raisingPostKinds);
	const selfGoverning = new Set(world.map.world.vocabularies.departmentKinds.filter((k) => k.selfGoverning).map((k) => k.id));
	const raisesRegiments = (id) => {
		const p = structure(id);
		if (p === undefined) return false;
		const dept = world.map.world.departments.find((d) => d.id === p.department);
		return raisingKinds.has(p.kind) && p.region !== null && !selfGoverning.has(dept?.kind ?? "");
	};
	// The posts as he believes them (0052; lane 1.12): a field post whose commander a battle took stays on his menu, with
	// the man he lost, until the report of it reaches him; an order he sends it meanwhile comes back undelivered.
	const ownPosts = receivedView.posts.filter((p) => side(p.post) === faction).map((p) => p.post).sort(strictCompare);
	const commandable = ownPosts.filter((id) => knownPosts.get(id).status === "held" && knownPosts.get(id).holder !== null && field(id)).map((id) => ({
		post: id,
		holder: knownPosts.get(id).holder,
		relays: relays(id),
		routes: routesTo(id),
		...receivedStrength(state, f.principal, id),
		raising: raisesRegiments(id),
		inTransit: inTransitTo(state, f.principal, id)
	}));
	const raising = receivedView.posts.filter((p) => p.status === "held" && p.holder !== null && (side(p.post) === faction || side(p.post) === null) && raisesRegiments(p.post)).map((p) => ({
		post: p.post,
		holder: p.holder,
		routes: routesTo(p.post),
		called: calledOn(state, f.principal, p.post)
	}));
	// Only received vacancies in commands held at the opening; unknown holders and unreceived losses stay unchanged.
	const heldAtStart = new Set(world.start.posts.filter((p) => p.holder !== null).map((p) => p.id));
	const vacancies = ownPosts.filter((id) => !formationPost(world.map, id) && knownPosts.get(id).status === "vacant" && heldAtStart.has(id) && field(id)).map((id) => ({
		post: id,
		arm: blocks(id).length > 0 && blocks(id).every((b) => isNaval(world.map, state, b)) ? "naval" : "land",
		routes: routesTo(id),
		appointing: inTransitTo(state, f.principal, id).includes("appoint")
	}));
	const previousCandidates = cache?.candidates.get(faction);
	let candidates;
	if (previousCandidates !== undefined && previousCandidates.world === world && previousCandidates.posts === receivedView.posts && previousCandidates.reports === receivedView.reports && previousCandidates.calendar === state.calendarStart) {
		candidates = previousCandidates.candidates;
	} else {
		candidates = receivedCandidates(world, state, f.principal, faction, null, receivedView);
		if (cache !== undefined) {
			// Prove the whole graph frozen before retaining it for another request.
			candidates = freezeDeep(candidates, cache);
			cache.candidates.set(faction, {
				world,
				posts: receivedView.posts,
				reports: receivedView.reports,
				calendar: state.calendarStart,
				candidates
			});
		}
	}
	const historicalAppointees = [];
	const historicalAppointments = [];
	const history = state.seatAssignments[seatIdFor(f.principal)]?.seatDriver === "rules";
	if (history) {
		const today = formatIsoDate(dateOfDay(state.calendarStart, state.stateDay + 1));
		const rows = world.map.world.rules.ruleSeats.principals.find((r) => r.faction === faction)?.appointments ?? [];
		// An effective date makes an unsent letter due. Attention can defer sending, but a refusal is final.
		// Read only the identity of the principal's own sent letter, not its private answer or willingness.
		const issued = (post, person) => {
			const sent = (id) => {
				if (id == null) return false;
				const day = Number(id.split(".")[1]);
				if (!Number.isSafeInteger(day)) return false;
				const expected = mintMessageId(new Set(), day, f.principal, person, `verb.appoint.${post}`);
				return id === expected || id.startsWith(`${expected}.`);
			};
			return state.messagesInTransit.some((m) => sent(m.id) || m.msgTo === f.principal && sent(m.msgReport?.reportAnswers)) || Object.values(state.orderResponses).some((r) => sent(r.respOrder)) || knowledgeOf(state, seatIdFor(f.principal)).knownReports.some((k) => sent(k.knownBody.reportAnswers));
		};
		const unsent = rows.filter((a) => "onDate" in a && !issued(a.post, a.person));
		historicalAppointees.push(...new Set(unsent.map((a) => a.person)));
		historicalAppointees.sort(strictCompare);
		for (const a of [...unsent].sort((a, b) => strictCompare(a.post, b.post) || strictCompare(a.person, b.person))) {
			if (!("onDate" in a) || a.onDate > today || !candidates.some((p) => p.person === a.person) || inTransitTo(state, f.principal, a.post).includes("appoint")) continue;
			const template = world.start.temporaryPosts.find((p) => p.id === a.post);
			const kind = world.map.world.vocabularies.postKinds.find((k) => k.id === template?.kind);
			const mayEstablish = template !== undefined && !knownPosts.has(a.post) && sides.get(template.department) === faction && kind?.creatable === "appoint" && kind.temporary && (template.parent === null || knownPosts.has(template.parent) && side(template.parent) === faction);
			if (!mayEstablish && (knownPosts.get(a.post)?.status !== "vacant" || side(a.post) !== faction)) continue;
			// The letter goes to the man, not to a post that does not exist yet (the appoint verb's own route).
			const to = capitalOf(state, faction);
			const routes = ORDER_ROUTES.flatMap((route) => {
				const l = routeLatency(ground.latency, world.rules.latency, route, to, to, faction, null);
				return l.ok ? [{
					route,
					typicalDays: l.latency.days,
					price: route === "special-messenger" ? world.rules.latency.specialMessengerPrice : 0
				}] : [];
			});
			historicalAppointments.push({
				post: a.post,
				person: a.person,
				routes
			});
		}
	}
	const situations = [];
	for (const def of world.situations) {
		const r = state.situationStates[def.id];
		if (def.faction !== faction || r === undefined || r.sitStatus !== "open" || r.sitSurfacedDay === null || r.sitDelegate !== null) continue;
		const proposers = new Set(def.options.filter((o) => r.sitOpenOptions.includes(o.id)).flatMap((o) => Array.isArray(o.proposedBy) ? o.proposedBy : []));
		const consultPosts = ownPosts.filter((post) => {
			const holder = knownPosts.get(post).holder;
			if (holder === null || holder === f.principal || !proposers.has(holder)) return false;
			// Only the identity of his own sent letter is read, never its actual response or an adviser's private stance.
			const tag = `verb.consult.${def.id}.${post}`;
			const sentTo = (id, person) => {
				if (id === null || id === undefined) return false;
				const issuedDay = Number(id.split(".")[1]);
				if (!Number.isSafeInteger(issuedDay)) return false;
				const expected = mintMessageId(new Set(), issuedDay, f.principal, person, tag);
				return id === expected || id.startsWith(`${expected}.`);
			};
			if (state.messagesInTransit.some((m) => m.msgVerb?.verbIssuer === f.principal && m.msgVerb.verbKind === "consult" && m.msgVerb.verbSubject === def.id && m.msgVerb.verbPost === post || m.msgTo === f.principal && sentTo(m.msgReport?.reportAnswers, m.msgReport?.reportAuthor ?? m.msgFrom))) return false;
			if (Object.values(state.orderResponses).some((a) => a.respKind === "verb:consult" && a.respPost === post && sentTo(a.respOrder, a.respPerson))) return false;
			return !knowledgeOf(state, seatIdFor(f.principal)).knownReports.some((k) => sentTo(k.knownBody.reportAnswers, k.knownBody.reportAuthor));
		});
		situations.push({
			...situationChoice(def, r.sitOpenOptions, def.delegableTo, null),
			consultPosts
		});
	}
	const awaiting = postsInStatus(state, "ready").filter((p) => state.planRecords[p].planIssuer === f.principal && !answerInTransit(state, f.principal, p, ["go"]));
	const d = world.map.world.rules.plans.goalDefaults;
	const doctrine = doctrineView(world, state, faction, receivedView);
	const appointments = world.map.world.rules.ruleSeats.principals.find((r) => r.faction === faction)?.appointments;
	const receivedPosts = receivedView.posts;
	const receivedSides = receivedDepartmentSides(world, receivedView);
	const appointmentView = appointments?.filter((a) => "fromDate" in a).map((a) => ({
		post: a.post,
		person: a.person,
		from: a.fromPost,
		ready: state.stateDay + 1 >= daysFromCivil(parseIsoDate(a.fromDate)) - daysFromCivil(parseIsoDate(state.calendarStart)) && receivedSides.get(a.requiresDepartment) === faction && receivedCandidates(world, state, f.principal, faction, a.fromPost, receivedView).some((p) => p.person === a.person) && !receivedPosts.some((p) => p.post === a.post),
		issued: state.messagesInTransit.some((m) => m.msgVerb?.verbKind === "appoint" && m.msgVerb.verbIssuer === f.principal && m.msgVerb.verbPost === a.post) || Object.values(state.orderResponses).some((r) => r.respKind === "verb:appoint" && r.respPost === a.post && r.respPerson === a.person),
		routes: routesTo(a.fromPost ?? a.post)
	}));
	return {
		menuKind: "principal",
		faction,
		atWarSince: warSince(world, state, faction),
		doctrine: appointmentView === undefined ? doctrine : {
			...doctrine,
			appointments: appointmentView
		},
		...history ? {
			historicalAppointments,
			historicalAppointees
		} : {},
		raising,
		vacancies,
		candidates,
		attention: {
			left: attentionLeft(state, seatIdFor(f.principal)),
			costs: world.map.world.rules.people.attention.costs,
			specialMessenger: world.rules.latency.specialMessengerPrice
		},
		commandable,
		situations,
		reviews: reviewsFor(state, f.principal),
		awaiting,
		goalDefaults: {
			risk: d.risk,
			deadlineDays: d.deadlineDays,
			rail: d.rail,
			river: d.river,
			sea: d.sea,
			neutral: d.neutral,
			awaitWord: d.awaitWord,
			approveAsDrafted: d.approveAsDrafted
		}
	};
}

function peopleProjection(world, principal, faction, reports, standingFor, day, calendar) {
	if (faction === null || !world.factionIds.includes(faction) || world.faction(faction).principal !== principal) {
		return Object.freeze({
			posts: Object.freeze([]),
			people: Object.freeze([])
		});
	}
	const departments = new Set(world.map.world.departments.filter((d) => d.faction === faction).map((d) => d.id));
	const posts = new Map();
	const knownSides = new Map();
	const serviceSides = new Map();
	const postDepartments = new Map();
	const people = new Set([principal]);
	const today = calendar === null ? null : formatIsoDate(dateOfDay(calendar, day));
	// The principal knows his own opening establishment, including unfilled offices. A foreign report reveals only
	// the post it names: the foreign start's holder and chain are not read to fill that gap.
	for (const p of world.start.posts) {
		if (!departments.has(p.department)) continue;
		const scheduled = today === null ? [] : [...p.departmentChanges].filter((c) => c.on <= today).sort((a, b) => strictCompare(a.on, b.on));
		postDepartments.set(p.id, scheduled.length === 0 ? p.department : scheduled[scheduled.length - 1].department);
		const parent = scheduled.length === 0 ? p.parent : scheduled[scheduled.length - 1].parent;
		posts.set(p.id, {
			post: p.id,
			parent,
			placementKnown: true,
			holder: p.holder,
			status: p.holder === null ? "vacant" : "held",
			vacantSince: null,
			source: null,
			asOfDay: 0,
			observerReports: []
		});
		if (p.holder !== null) people.add(p.holder);
	}
	const received = reports.filter((r) => r.day <= day && r.receivedDay <= day);
	const chronological = [...received].sort((a, b) => a.day - b.day || (a.hour ?? -1) - (b.hour ?? -1) || strictCompare(a.id, b.id));
	const ensure = (id) => {
		const old = posts.get(id);
		if (old !== undefined) return old;
		// Once a paper names a post, its public department can identify a government notice.
		// Its opening holder and parent still supply no evidence about who holds it now.
		const opening = world.start.posts.find((p) => p.id === id);
		if (opening !== undefined) postDepartments.set(id, opening.department);
		const unknown = {
			post: id,
			parent: null,
			placementKnown: false,
			holder: null,
			status: "unknown",
			vacantSince: null,
			source: null,
			asOfDay: 0,
			observerReports: []
		};
		posts.set(id, unknown);
		return unknown;
	};
	const tell = (id, holder, status, r) => {
		const old = ensure(id);
		posts.set(id, {
			...old,
			holder,
			status,
			vacantSince: status === "vacant" ? r.day : null,
			source: r.id,
			asOfDay: r.day
		});
		if (holder !== null) people.add(holder);
	};
	for (const r of chronological) {
		// A notice's received paper identifies the public act. Never inspect whether its event fired in State,
		// and never interpret a decision's possible effects as an announcement that they happened.
		if (r.subjectKind === "situation") {
			const notice = world.situations.find((s) => s.id === r.subjectId);
			if (notice?.kind === "notice" && notice.report?.reportType === r.type && notice.report.subtype === r.subtype) {
				for (const effect of notice.effects) {
					if (!("propose" in effect)) continue;
					const p = effect.propose;
					if (p.owner === "command" && p.field === "department_side" && p.subject !== null && p.side !== null && p.delta > 0) knownSides.set(p.subject, p.side);
					if (p.owner === "command" && p.field === "post_succession" && p.subject !== null && p.succession !== undefined && p.succession !== null && p.delta > 0) {
						const old = ensure(p.subject);
						if (old.status === "unknown" || old.holder === p.succession.from) tell(p.subject, p.succession.to, p.succession.to === null ? "vacant" : "held", r);
					}
				}
			}
		}
		for (const via of r.via) ensure(via);
		people.add(r.author);
		if (r.subjectKind === "person") people.add(r.subjectId);
		const resigned = r.type === "wire-dispatch" && r.subtype === null && r.subjectKind === "person" && r.subjectId === r.author && r.claims.some((c) => c.kind === "service-choice" && c.token === "resign" && c.value === 1);
		if (resigned) {
			// The letter supplies the act; the public service row supplies its destination, never hidden personService.
			serviceSides.set(r.author, world.map.world.people.find((p) => p.id === r.author)?.service?.toFaction ?? null);
			if (r.authorPost !== null) {
				const old = ensure(r.authorPost);
				if (old.holder === null && old.status === "unknown") tell(r.authorPost, null, "vacant", r);
			}
			for (const post of posts.values()) if (post.holder === r.author) tell(post.post, null, "vacant", r);
		} else if (r.authorPost !== null) tell(r.authorPost, r.author, "held", r);
		if (r.subjectKind !== "post") continue;
		const post = r.subjectId;
		ensure(post);
		if (r.type === "observer-letter") {
			const old = ensure(post);
			posts.set(post, {
				...old,
				observerReports: [...old.observerReports, r.id]
			});
		}
		for (const c of r.claims) {
			if (c.kind === "organisation-post") {
				const template = (world.map.world.organisationTemplates ?? []).find((t) => t.posts.some((p) => p.id === post));
				const spec = template?.posts.find((p) => p.id === post);
				const army = world.start.posts.find((p) => p.id === template?.army) ?? world.start.temporaryPosts.find((p) => p.id === template?.army);
				if (spec !== undefined && army !== undefined && r.authorPost === template.army && (departments.has(army.department) || knownSides.get(army.department) === faction)) {
					postDepartments.set(post, army.department);
					posts.set(post, {
						...ensure(post),
						parent: c.token,
						placementKnown: true
					});
					tell(post, c.commander ?? null, c.commander == null ? "vacant" : "held", r);
				}
			} else if (c.kind === "commander-lost" || c.kind === "order-returned" && c.token === "vacant_post" || c.kind === "verb-answered" && c.token?.startsWith("relieve:") && c.value === 1) tell(post, null, "vacant", r);
			else if (c.kind === "appointment-refused" && c.token === "post_held") tell(post, null, "unknown", r);
			else if (c.kind === "order-returned" && [
				"holder_changed",
				"not_serving",
				"other_side",
				"not_raising_post"
			].includes(c.token ?? "")) tell(post, null, "unknown", r);
			else if (c.kind === "verb-answered" && c.token?.startsWith("appoint:") && c.value === 1) {
				// A received acceptance of our declared establishment identifies its public parent, never a live chain.
				const declared = world.start.temporaryPosts.find((p) => p.id === post);
				if (declared !== undefined && (departments.has(declared.department) || knownSides.get(declared.department) === faction)) {
					postDepartments.set(post, declared.department);
					posts.set(post, {
						...ensure(post),
						parent: declared.parent,
						placementKnown: true
					});
				}
				tell(post, r.author, "held", r);
			}
		}
	}
