		let side = world.personIds.includes(person) ? world.person(person).faction : null;
		for (const post of posts.values()) {
			if (post.holder !== person) continue;
			const department = postDepartments.get(post.post);
			if (department !== undefined && knownSides.has(department)) side = knownSides.get(department);
		}
		// An explicit service choice supersedes the side inferred from a government's posts (0101, R76).
		if (serviceSides.has(person)) side = serviceSides.get(person);
		const stances = [];
		const assessments = [];
		for (const r of chronological) {
			if (r.author === person && r.type === "advice" && r.subtype === "requested" && r.advice !== null && r.claims.some((c) => c.kind === "verb-answered" && c.token?.startsWith("consult:") && c.value === 1)) {
				stances.push(Object.freeze({
					subjectKind: r.subjectKind,
					subjectId: r.subjectId,
					recommends: r.advice.recommends,
					confidence: r.advice.confidence,
					day: r.day,
					source: r.id
				}));
			}
			if (r.author !== person && r.subjectKind === "person" && r.subjectId === person && r.type === "advice" && r.advice !== null) assessments.push(r.id);
		}
		return Object.freeze({
			person,
			standing: side === faction ? standingFor(person) : null,
			stances: Object.freeze(stances),
			assessments: Object.freeze(assessments)
		});
	});
	return Object.freeze({
		posts: Object.freeze([...posts.values()].sort((a, b) => strictCompare(a.post, b.post)).map((p) => Object.freeze({
			...p,
			observerReports: Object.freeze([...p.observerReports])
		}))),
		people: Object.freeze(personViews)
	});
}

function allCommandedBlocks(map, state, post) {
	const templates = map.world.organisationTemplates ?? [];
	const formationIds = new Set(templates.flatMap((t) => t.posts.map((p) => p.id)));
	if (!templates.some((t) => t.army === post) && !formationIds.has(post)) return commandedBlocks(state, post);
	return Object.keys(state.forceAssignments).filter((id) => {
		const assigned = state.forceAssignments[id] ?? null;
		return assigned === post || assigned !== null && formationIds.has(assigned) && withinCommand(state, assigned, post);
	}).sort(strictCompare);
}

function withinCommand(state, post, command) {
	const seen = new Set();
	while (post !== null && !seen.has(post)) {
		if (post === command) return true;
		seen.add(post);
		post = postStateOf(state, post).postParent;
	}
	return false;
}

function headquartersOf(world, state, post) {
	const faction = postFaction(world, state, post);
	if (faction !== null && world.factionIds.includes(faction) && state.postStates[post]?.postHolder === world.faction(faction).principal) return capitalOf(state, faction);
	// Institutional offices stay with their government even when they own distant forces.
	if (postRole(world, state, post) === "office") {
		if (faction !== null && world.factionIds.includes(faction)) return capitalOf(state, faction);
		const seat = postStateOf(state, post).postSeat;
		if (seat !== null) return seat;
		throw new RangeError(`office ${post} has no government's seat`);
	}
	const body = mainBody(state, post, world.map.forceTotalsCache, world.map);
	if (body !== null) return state.forceLocations[body].locRegion;
	const p = postStateOf(state, post);
	if (p.postSeat !== null) return p.postSeat;
	if (faction !== null && world.factionIds.includes(faction)) return capitalOf(state, faction);
	throw new RangeError(`post ${post} has no blocks, no seat and no side's capital to stand in`);
}

function mainBody(state, post, cache, map) {
	let best = null;
	let bestMen = -1;
	for (const b of map === undefined ? commandedBlocks(state, post) : allCommandedBlocks(map, state, post)) {
		const men = forceTotals(state.forceBlockStates[b], cache).fbStrength ?? 0;
		if (men > bestMen) {
			best = b;
			bestMen = men;
		}
	}
	return best;
}

function postRole(world, state, post) {
	return world.roleOf(postStateOf(state, post).postKind);
}

